val icon: @Composable (MonarchSaveStatus) -> Unit = { status ->
    MonarchIcon(
        when (status) {
            MonarchSaveStatus.Saved -> SampleIcons.Check
            MonarchSaveStatus.Unsaved -> SampleIcons.Dot
            else -> SampleIcons.Warning
        },
        contentDescription = null,
        size = MonarchIconSize.Sm,
    )
}
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
    MonarchSaveStatusIndicator(status = MonarchSaveStatus.{{states.0|pascal}}, labels = labels, icon = icon)
    MonarchSaveStatusIndicator(status = MonarchSaveStatus.{{states.1|pascal}}, labels = labels, icon = icon)
    MonarchSaveStatusIndicator(
        status = MonarchSaveStatus.{{states.2|pascal}},
        savedAt = System.currentTimeMillis() - {{savedAgoSeconds}} * 1000L,
        labels = labels,
        icon = icon,
    )
    MonarchSaveStatusIndicator(status = MonarchSaveStatus.{{states.3|pascal}}, labels = labels, icon = icon, onRetry = {})
}

